    return "ArithmeticPostAggregator{" +
           "name='" + name + '\'' +
           ", fnName='" + fnName + '\'' +
           ", fields=" + fields +
           ", op=" + op +
           '}';
  }

  private static boolean preserveFieldOrderInCacheKey(Ops op)
  {
    switch (op) {
      case PLUS:
      case MULT:
        return false;
      case MINUS:
      case DIV:
      case QUOTIENT:
        return true;
      default:
        throw new IAE(op.fn);
    }
  }

  private enum Ops
  {
    PLUS("+") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs + rhs;
      }
    },
    MINUS("-") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs - rhs;
      }
    },
    MULT("*") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs * rhs;
      }
    },
    DIV("/") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return (rhs == 0.0) ? 0 : (lhs / rhs);
      }
    },
    QUOTIENT("quotient") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs / rhs;
      }
    };

    private static final Map<String, Ops> LOOKUP_MAP = new HashMap<>();

    static {
      for (Ops op : Ops.values()) {
        LOOKUP_MAP.put(op.getFn(), op);
      }
    }

    private final String fn;

    Ops(String fn)
    {
      this.fn = fn;
    }

    public String getFn()
    {
      return fn;
    }

    public abstract double compute(double lhs, double rhs);

    static Ops lookup(String fn)
    {
      return LOOKUP_MAP.get(fn);
    }

    static Set<String> getFns()
    {
      return LOOKUP_MAP.keySet();
    }
  }

  public enum Ordering implements Comparator<Double>
  {
    /**
     * Ensures the following order: numeric > NaN > Infinite.
     *
     * The name may be referenced via {@link #valueOf(String)} in the constructor {@link
     * ArithmeticPostAggregator#ArithmeticPostAggregator(String, String, List, String)}.
     */
    @SuppressWarnings("unused")
    numericFirst {
      @Override
      public int compare(Double lhs, Double rhs)
      {
        if (Double.isFinite(lhs) && !Double.isFinite(rhs)) {
          return 1;
        }
        if (!Double.isFinite(lhs) && Double.isFinite(rhs)) {
          return -1;
        }
        return Double.compare(lhs, rhs);
      }
    }
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    ArithmeticPostAggregator that = (ArithmeticPostAggregator) o;

    if (!comparator.equals(that.comparator)) {
      return false;
    }
    if (!fields.equals(that.fields)) {
      return false;
    }
    if (!fnName.equals(that.fnName)) {
      return false;
    }
    if (name != null ? !name.equals(that.name) : that.name != null) {
      return false;
    }
    if (op != that.op) {
      return false;
    }
    if (ordering != null ? !ordering.equals(that.ordering) : that.ordering != null) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode()
  {
    int result = name != null ? name.hashCode() : 0;
    result = 31 * result + fnName.hashCode();
    result = 31 * result + fields.hashCode();
    result = 31 * result + op.hashCode();
    result = 31 * result + comparator.hashCode();
    result = 31 * result + (ordering != null ? ordering.hashCode() : 0);
    return result;
  }

  public List<PostAggregator> decoratePostAggregatorList(
      List<PostAggregator> postAggs,
      Map<String, AggregatorFactory> aggFactories
  )
  {
    this.workingPostAggs = postAggs;
    this.fields = this.workingPostAggs;
    this.workingAggMap = aggFactories;
    List<PostAggregator> decorated = Lists.newArrayListWithExpectedSize(workingPostAggs.size());
    for (PostAggregator aggregator : workingPostAggs) {
      decorated.add(aggregator.decorate(workingAggMap));
    }
    return decorated;
  }

  public List<PostAggregator> prepareAggregations(
      List<AggregatorFactory> aggFactories,
      List<PostAggregator> postAggs
  )
  {
    this.workingAggs = aggFactories;
    this.workingPostAggs = postAggs;
    this.fields = this.workingPostAggs;
    this.workingOutputNames = Collections.emptyList();
    return prepareAggregations(workingOutputNames, workingAggs, workingPostAggs);
  }

  public List<PostAggregator> prepareAggregations(
      List<String> otherOutputNames,
      List<AggregatorFactory> aggFactories,
      List<PostAggregator> postAggs
  )
  {
    this.workingOutputNames = Preconditions.checkNotNull(otherOutputNames, "otherOutputNames cannot be null");
    this.workingAggs = Preconditions.checkNotNull(aggFactories, "aggregations cannot be null");
    this.workingPostAggs = postAggs;
    this.fields = this.workingPostAggs;
    this.workingAggMap = new HashMap<>();

    final Set<String> combinedOutputNames = new HashSet<>(workingOutputNames);
    for (AggregatorFactory aggFactory : workingAggs) {
      Preconditions.checkArgument(
          combinedOutputNames.add(aggFactory.getName()),
          "[%s] already defined", aggFactory.getName()
      );
      workingAggMap.put(aggFactory.getName(), aggFactory);
    }

    if (workingPostAggs != null && !workingPostAggs.isEmpty()) {
      List<PostAggregator> decorated = Lists.newArrayListWithExpectedSize(workingPostAggs.size());
      for (final PostAggregator postAgg : workingPostAggs) {
        final Set<String> dependencies = postAgg.getDependentFields();
        final Set<String> missing = Sets.difference(dependencies, combinedOutputNames);

        Preconditions.checkArgument(
            missing.isEmpty(),
            "Missing fields [%s] for postAggregator [%s]", missing, postAgg.getName()
        );
        Preconditions.checkArgument(
            combinedOutputNames.add(postAgg.getName()),
            "[%s] already defined", postAgg.getName()
        );

        decorated.add(postAgg.decorate(workingAggMap));
      }
      return decorated;
    }

    return workingPostAggs;
  }

  public List<PostAggregator> pruneDependentPostAgg(List<PostAggregator> postAggregatorList, String postAggName)
  {
    this.workingPostAggs = postAggregatorList;
    this.fields = this.workingPostAggs;
    this.workingMetricName = postAggName;
    this.workingDependencies = new HashSet<>();
    workingDependencies.add(workingMetricName);

    ArrayList<PostAggregator> rv = new ArrayList<>();
    for (PostAggregator agg : Lists.reverse(workingPostAggs)) {
      if (workingDependencies.contains(agg.getName())) {
        rv.add(agg);
        workingDependencies.remove(agg.getName());
        workingDependencies.addAll(agg.getDependentFields());
      }
    }

    Collections.reverse(rv);
    return rv;
  }

  public Pair<List<AggregatorFactory>, List<PostAggregator>> condensedAggregators(
      List<AggregatorFactory> aggList,
      List<PostAggregator> postAggList,
      String metric
  )
  {
    this.workingAggs = aggList;
    this.workingPostAggs = postAggList;
    this.fields = this.workingPostAggs;
    this.workingMetricName = metric;
    List<PostAggregator> condensedPostAggs = pruneDependentPostAgg(workingPostAggs, workingMetricName);
    this.workingDependencies = new HashSet<>();
    workingDependencies.add(workingMetricName);
    for (PostAggregator postAggregator : condensedPostAggs) {
      workingDependencies.addAll(postAggregator.getDependentFields());
    }

    List<AggregatorFactory> condensedAggs = new ArrayList<>();
    for (AggregatorFactory aggregatorSpec : workingAggs) {
      if (workingDependencies.contains(aggregatorSpec.getName())) {
        condensedAggs.add(aggregatorSpec);
      }
    }
    return new Pair<>(condensedAggs, condensedPostAggs);
  }

  public Set<String> collectDependentFields(List<PostAggregator> postAggregatorFields)
  {
    this.workingPostAggs = postAggregatorFields;
    this.fields = this.workingPostAggs;
    Set<String> dependentFields = new HashSet<>();
    for (PostAggregator field : workingPostAggs) {
      dependentFields.addAll(field.getDependentFields());
    }
    return dependentFields;
  }

  public Object computeDoubleGreatest(List<PostAggregator> postAggregatorFields, Map<String, Object> values)
  {
    this.workingPostAggs = postAggregatorFields;
    this.fields = this.workingPostAggs;
    Comparator<Number> greatestComparator = Comparator.nullsFirst(
        Comparator.comparingDouble(Number::doubleValue)
    );
    Iterator<PostAggregator> fieldsIter = workingPostAggs.iterator();
    Double retVal = NullHandling.replaceWithDefault() ? Double.NEGATIVE_INFINITY : null;
    while (fieldsIter.hasNext()) {
      Number nextVal = ((Number) fieldsIter.next().compute(values));
      if (nextVal != null && (retVal == null || greatestComparator.compare(nextVal, retVal) > 0)) {
        if (nextVal instanceof Double) {
          retVal = (Double) nextVal;
        } else {
          retVal = nextVal.doubleValue();
        }
      }
    }
    return retVal;
  }

  public Object computeDoubleLeast(List<PostAggregator> postAggregatorFields, Map<String, Object> values)
  {
    this.workingPostAggs = postAggregatorFields;
    this.fields = this.workingPostAggs;
    Comparator<Number> leastComparator = Comparator.nullsLast(
        Comparator.comparingDouble(Number::doubleValue)
    );
    Iterator<PostAggregator> fieldsIter = workingPostAggs.iterator();
    Double retVal = NullHandling.replaceWithDefault() ? Double.POSITIVE_INFINITY : null;
    while (fieldsIter.hasNext()) {
      Number nextVal = ((Number) fieldsIter.next().compute(values));
      if (nextVal != null && (retVal == null || leastComparator.compare(nextVal, retVal) < 0)) {
        if (nextVal instanceof Double) {
          retVal = (Double) nextVal;
        } else {
          retVal = nextVal.doubleValue();
        }
      }
    }
    return retVal;
  }

  public Object computeLongGreatest(List<PostAggregator> postAggregatorFields, Map<String, Object> values)
