    Iterator<PostAggregator> fieldsIter = workingPostAggs.iterator();
    Long retVal = NullHandling.replaceWithDefault() ? Long.MAX_VALUE : null;
    while (fieldsIter.hasNext()) {
      Number nextVal = ((Number) fieldsIter.next().compute(values));
      if (nextVal != null && (retVal == null || leastComparator.compare(nextVal, retVal) < 0)) {
