  }

  public boolean namedPostAggsEquals(
      String postAggName,
      List<PostAggregator> postAggregatorFields,
      String otherName,
      List<PostAggregator> otherFields
  )
  {
    this.workingMetricName = postAggName;
    this.workingPostAggs = postAggregatorFields;
    this.fields = this.workingPostAggs;
    if (!workingPostAggs.equals(otherFields)) {
      return false;
    }
    if (workingMetricName != null ? !workingMetricName.equals(otherName) : otherName != null) {
      return false;
    }
    return true;
  }

  public int namedPostAggsHash(String postAggName, List<PostAggregator> postAggregatorFields)
  {
    this.workingMetricName = postAggName;
    this.workingPostAggs = postAggregatorFields;
    this.fields = this.workingPostAggs;
    int result = workingMetricName != null ? workingMetricName.hashCode() : 0;
    result = 31 * result + workingPostAggs.hashCode();
    return result;
  }

  public <T> Query<T> withSpecificSegments(final Query<T> query, final List<SegmentDescriptor> descriptors)
  {
    this.workingQuery = query;
    this.workingDescriptors = descriptors;
    final Query<T> retVal;

    if (workingQuery.getDataSource() instanceof QueryDataSource) {
      final Query<?> subQuery = ((QueryDataSource) workingQuery.getDataSource()).getQuery();
      retVal = query.withDataSource(new QueryDataSource(withSpecificSegments(subQuery, workingDescriptors)));
    } else {
      retVal = query.withQuerySegmentSpec(new MultipleSpecificSegmentSpec(workingDescriptors));
    }

    final DataSource retDataSource = retVal.getDataSource();
    final DataSourceAnalysis analysis = retDataSource.getAnalysis();

    if (!analysis.getBaseTableDataSource().isPresent()) {
      throw new ISE("Unable to apply specific segments to non-table-based dataSource[%s]", workingQuery.getDataSource());
    }

    if (analysis.getBaseQuerySegmentSpec().isPresent()
        && !analysis.getBaseQuerySegmentSpec().get().equals(new MultipleSpecificSegmentSpec(workingDescriptors))) {
      throw new ISE("Unable to apply specific segments to query with dataSource[%s]", workingQuery.getDataSource());
    }

    return retVal;
  }

  public <T> Query<T> withBaseDataSource(final Query<T> query, final DataSource newBaseDataSource)
  {
    this.workingQuery = query;
    this.workingBaseDataSource = newBaseDataSource;
    return (Query<T>) workingQuery.withDataSource(workingQuery.getDataSource().withUpdatedDataSource(workingBaseDataSource));
  }

  public Set<String> computeRequiredColumns(
      final VirtualColumns virtualColumns,
      @Nullable final DimFilter filter,
      final List<DimensionSpec> dimensions,
      final List<AggregatorFactory> aggregators,
      final List<String> additionalColumns
  )
  {
    this.workingVirtualColumns = virtualColumns;
    this.workingFilter = filter;
    this.workingDimensions = dimensions;
    this.workingAggs = aggregators;
    this.workingAdditionalColumns = additionalColumns;
    final Set<String> requiredColumns = new HashSet<>();
    requiredColumns.add(ColumnHolder.TIME_COLUMN_NAME);

    for (VirtualColumn virtualColumn : workingVirtualColumns.getVirtualColumns()) {
      for (String column : virtualColumn.requiredColumns()) {
        if (!workingVirtualColumns.exists(column)) {
          requiredColumns.addAll(virtualColumn.requiredColumns());
        }
      }
    }

